def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal
    if (not (0 <= start_row < rows and 0 <= start_col < cols)) or grid[start_row][start_col] == '#':
        return []
    if (not (0 <= goal_row < rows and 0 <= goal_col < cols)) or grid[goal_row][goal_col] == '#':
        return []
    if start == goal:
        return [start]
    deltas = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    stack = [(start_row, start_col, 0, [start])]
    while stack:
        r, c, dir, path = stack.pop()
        if (r, c) == goal:
            return path
        order = [(dir + 1) % 4, dir, (dir - 1) % 4, (dir + 2) % 4]
        for new_dir in reversed(order):
            nr = r + deltas[new_dir][0]
            nc = c + deltas[new_dir][1]
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == '.' and (nr, nc) not in path:
                    new_path = path + [(nr, nc)]
                    stack.append((nr, nc, new_dir, new_path))
    return []

