import heapq

def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]
    rows = len(grid)
    cols = len(grid[0])
    dist = {start: 0}
    prev = {}
    heap = [(0, start)]
    while heap:
        current_dist, current = heapq.heappop(heap)
        if current == goal:
            break
        if current in dist and current_dist > dist[current]:
            continue
        r, c = current
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                if (nr, nc) not in dist or current_dist + 1 < dist[(nr, nc)]:
                    dist[(nr, nc)] = current_dist + 1
                    prev[(nr, nc)] = current
                    heapq.heappush(heap, (current_dist + 1, (nr, nc)))
    if goal not in prev:
        return []
    path = []
    current = goal
    while current != start:
        path.append(current)
        current = prev[current]
    path.append(start)
    return path[::-1]

