def solve(grid, start, goal):
    from heapq import heappush, heappop

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    heap = []
    heappush(heap, (0, start[0], start[1]))
    visited = set()
    visited.add((start[0], start[1]))
    parent = {}
    found = False
    goal_node = None

    while heap:
        dist, r, c = heappop(heap)
        current = (r, c)
        if current == goal:
            found = True
            goal_node = current
            break
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == '.' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    parent[(nr, nc)] = current
                    heappush(heap, (dist + 1, nr, nc))

    if not found:
        return []
    else:
        path = []
        current = goal_node
        while current in parent:
            path.append(current)
            current = parent[current]
        path.append(start)
        path.reverse()
        return path

def solve(grid, start, goal):
    def is_valid(pos):
        row, col = pos
        if row < 0 or row >= len(grid):
            return False
        if col < 0 or col >= len(grid[0]):
            return False
        return grid[row][col] == '.'

    if not is_valid(start) or not is_valid(goal):
        return []
    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = [[False for _ in range(len(grid[0]))] for _ in range(len(grid))]
    path = []

    def dfs(current, path_so_far):
        row, col = current
        path_so_far.append(current)
        visited[row][col] = True
        if current == goal:
            path.clear()
            path.extend(path_so_far)
            return True
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            new_pos = (new_row, new_col)
            if is_valid(new_pos) and not visited[new_row][new_col]:
                if dfs(new_pos, path_so_far):
                    return True
        path_so_far.pop()
        visited[row][col] = False
        return False

    if dfs(start, []):
        return path
    else:
        return []

