import heapq

def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0]) if rows > 0 else 0

    # Check if start or goal are out of bounds
    if (not (0 <= start[0] < rows and 0 <= start[1] < cols) or 
        not (0 <= goal[0] < rows and 0 <= goal[1] < cols)):
        return []

    # Check if start or goal are walls
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    heap = [(0, start)]
    visited = set()
    parent = {}

    while heap:
        dist, current = heapq.heappop(heap)

        if current in visited:
            continue

        if current == goal:
            path = []
            node = current
            while node != start:
                path.append(node)
                node = parent[node]
            path.reverse()
            path = [start] + path
