import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    srow, scol = start
    grow, gcol = goal
    if grid[srow][scol] == '#' or grid[grow][gcol] == '#':
        return []
    directions = [(-1,0), (1,0), (0,-1), (0,1)]
    heap = []
    heapq.heappush(heap, (srow, scol, srow, scol))
    visited = set()
    predecessor = {}
    found = False
    while heap:
        pr_r, pr_c, current_r, current_c = heapq.heappop(heap)
        current = (current_r, current_c)
        if current in visited:
            continue
        visited.add(current)
        if current == goal:
            found = True
            break
        for dr, dc in directions:
            nr = current_r + dr
            nc = current_c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == '.':
                    heapq.heappush(heap, (nr, nc, nr, nc))
                    predecessor[(nr, nc)] = current
    if not found:
        return []
    path = []
    current = goal
    while current != start:
        path.append(current)
        current = predecessor.get(current)
        if current is None:
            return []
    path.append(start)
    path.reverse()
    return path

